"""Output guard: nothing generated by a model may read as an investment opinion.

The product judges *messages*, never securities. Any model-written text is
checked here before it reaches the user; if it fails, the vetted template text
is used instead. Template text never goes through a model, so it is not
filtered (the templates *describe* target-price scams, which is allowed).
"""
from __future__ import annotations

import re

_ADVICE = [
    r"\b(?:you\s+should|i\s+(?:recommend|suggest)|we\s+(?:recommend|suggest)|consider|try\s+to)\s+(?:\w+\s+){0,3}(?:buy|sell|hold|invest|accumulate|short)\b",
    r"\b(?:buy|sell|hold|accumulate|short)\s+(?:the\s+|this\s+|that\s+|these\s+|those\s+|some\s+)?(?:stock|stocks|share|shares|scrip|equity|equities|fund|mutual\s+fund|crypto|coin|nifty|sensex|etf)\b",
    r"\btarget\s+price\b",
    r"\b(?:good|great|best|safe|smart)\s+(?:investment|stock|buy|bet)\b",
    r"\b(?:will|likely\s+to|expected\s+to)\s+(?:rise|go\s+up|fall|double|grow|rally|crash)\b",
    r"\bexpected\s+returns?\b",
    r"வாங்குங்கள்|விற்கவும்|வாங்கவும்",
    r"खरीदें|खरीदिए|बेचें|बेचिए",
]
_ADVICE_RX = [re.compile(p, re.IGNORECASE | re.UNICODE) for p in _ADVICE]
_NUM = re.compile(r"\d+")
_URL = re.compile(r"(?:https?://|www\.)\S+", re.IGNORECASE)


def violates(text: str) -> str | None:
    """Return the first matching advice pattern, or None if the text is clean."""
    for rx in _ADVICE_RX:
        m = rx.search(text)
        if m:
            return m.group(0)
    return None


def is_safe(model_text: str, allowed_source: str) -> bool:
    """True if model_text contains no advice language and invents no numbers or links.

    ``allowed_source`` is the text the model was given; any digit run or URL in
    the output must already appear in it.
    """
    if not model_text or len(model_text) > 900:
        return False
    if violates(model_text):
        return False
    if _URL.search(model_text) and not _URL.search(allowed_source):
        return False
    src_nums = set(_NUM.findall(allowed_source))
    return all(n in src_nums for n in _NUM.findall(model_text))
